import{af as d,ad as r,z as u,J as c,ab as l,x as o,C as i,K as t,y as n}from"./chunks/framework.CMN4K1q-.js";const y=JSON.parse('{"title":"Survey","description":"","frontmatter":{"outline":[2,3]},"headers":[],"relativePath":"devices/api/sdks/toit/applications/survey/index.md","filePath":"devices/api/sdks/toit/applications/survey/index.md"}'),p={name:"devices/api/sdks/toit/applications/survey/index.md"};function h(f,e,m,g,b,w){const a=r("PluginTabsTab"),s=r("PluginTabs");return u(),c("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1792747256000"},[e[13]||(e[13]=l('<h1 id="survey" tabindex="-1">Survey <a class="header-anchor" href="#survey" aria-label="Permalink to &quot;Survey&quot;">​</a></h1><p>The survey application is designed for easily demoing the Toit capabilities of the RH2 device.</p><p>When installed on an RH2 Device, it is accessible via the <code>Actions</code> menu of the <a href="/docs/pr/24/devices/rtk/handheld/application">main screen</a>.</p><p>The application allows for collecting up to 100 GNSS points with or without RTK correction data, either manually or automatically based on distance, and sending them to the cloud for further processing or viewing (via <a href="/docs/pr/24/apps/chasm/share/">share.chasm.cloud</a>).</p><h2 id="interface" tabindex="-1">Interface <a class="header-anchor" href="#interface" aria-label="Permalink to &quot;Interface&quot;">​</a></h2><p>The application is designed to be used with the RH2 device, and its button interface.</p><p>Many screens present options above the buttons, which can be selected using the corresponding button.</p><p>When in a menu, the left and right buttons can be used to navigate between options, with the center button used to select the currently highlighted option.</p><p>The application is split into three main screens. Depending on how the application is loaded onto the device, you may also find an initial App selection menu.</p><h3 id="apps" tabindex="-1">Apps <a class="header-anchor" href="#apps" aria-label="Permalink to &quot;Apps&quot;">​</a></h3><p>The app selection screen allows selecting any of the installed applications on the device, including the ability to switch back to the main device application, or reboot the device.</p><figure><img src="https://upload.r2.lb.chasm.cloud/2025/10/ApplicationFrameHost_I8ns15cyLB.png" alt="" width="500" tabindex="0"><figcaption></figcaption></figure><p>You can select the <code>Survey</code> options to launch the survey application, by navigating to it and pressing the center button.</p><h3 id="home" tabindex="-1">Home <a class="header-anchor" href="#home" aria-label="Permalink to &quot;Home&quot;">​</a></h3><p>When the survey application is launched, you will be presented with the home screen, including the standard device status bar, as well as new button options, and information that will be populated while the survey is in progress.</p><p>This screen can take a few forms, depending on the current state of the application.</p><p>When the application is idle, the screen will prompt you to <a href="#surveying">start a new survey</a>, or navigate to the <a href="#info">Info</a> or <a href="#actions">Actions</a> screens.</p>',17)),o(s,null,{default:i(()=>[o(a,{label:"E-Ink"},{default:i(()=>[...e[0]||(e[0]=[t("figure",null,[t("img",{src:"https://upload.r2.lb.chasm.cloud/2025/10/ApplicationFrameHost_8CTt8Sv1FG.png",alt:"",width:"500",tabindex:"0"}),t("figcaption")],-1)])]),_:1}),o(a,{label:"Web App"},{default:i(()=>[...e[1]||(e[1]=[t("figure",null,[t("img",{src:"https://upload.r2.lb.chasm.cloud/2025/10/chrome_erGwlLVCvH.png",alt:"",width:"500",tabindex:"0"}),t("figcaption")],-1)])]),_:1})]),_:1}),e[14]||(e[14]=t("p",null,"If the device is configured to have a WiFi connection, you'll also find the device accessible via a basic web interface, mirroring the information on the device screen, and sub menus.",-1)),e[15]||(e[15]=t("p",null,[n("When "),t("a",{href:"#surveying"},"surveying"),n(" is in progress, the screen will update to show the current status of the survey, including GNSS fix information, and the number of points collected.")],-1)),e[16]||(e[16]=t("h3",{id:"info",tabindex:"-1"},[n("Info "),t("a",{class:"header-anchor",href:"#info","aria-label":'Permalink to "Info"'},"​")],-1)),e[17]||(e[17]=t("p",null,[n("The "),t("code",null,"Info"),n(" screen displays information about the application connectivity.")],-1)),o(s,null,{default:i(()=>[o(a,{label:"WiFi mode"},{default:i(()=>[...e[2]||(e[2]=[t("figure",null,[t("img",{src:"https://upload.r2.lb.chasm.cloud/2025/10/ApplicationFrameHost_raFyujiYaE.png",alt:"",width:"500",tabindex:"0"}),t("figcaption")],-1)])]),_:1}),o(a,{label:"AP mode"},{default:i(()=>[...e[3]||(e[3]=[t("figure",null,[t("img",{src:"https://upload.r2.lb.chasm.cloud/2025/10/chrome_8Fhippah0Y.png",alt:"",width:"500",tabindex:"0"}),t("figcaption")],-1)])]),_:1})]),_:1}),e[18]||(e[18]=l('<ul><li><strong>Share</strong>: A random code associated with this load of the survey application, which can be used to retrieve any cloud submitted data using <a href="/docs/pr/24/apps/chasm/share/">share.chasm.cloud</a>. The share code to enter into the viewer will be the date of submission, follow by the share code, e.g. <code>20250930-af3ge911e5</code>.</li><li><strong>Conn</strong> : Will either be <code>WiFi</code> or <code>WiFi AP</code>, depending on the current connectivity mode. If not WiFi credentials are configured on the ESP32, then this will always be <code>WiFi AP</code>, where the device will run its own access point (and also display connection details)</li><li><strong>IP</strong> : The current IP address of the device on the WiFi network, or the access point IP if in AP mode.</li><li><strong>WiFi Net</strong> : The SSID of the WiFi network the device is connected to (if in station mode).</li><li><strong>AP Name</strong> : The SSID of the access point the device is running (if in AP mode).</li><li><strong>AP Pass</strong> : The password of the access point the device is running (if in AP mode).</li></ul><h3 id="actions" tabindex="-1">Actions <a class="header-anchor" href="#actions" aria-label="Permalink to &quot;Actions&quot;">​</a></h3>',2)),o(s,null,{default:i(()=>[o(a,{label:"Menu page 1"},{default:i(()=>[...e[4]||(e[4]=[t("figure",null,[t("img",{src:"https://upload.r2.lb.chasm.cloud/2025/10/ApplicationFrameHost_y4UbjFOr5N.png",alt:"",width:"500",tabindex:"0"}),t("figcaption")],-1)])]),_:1}),o(a,{label:"Menu page 2"},{default:i(()=>[...e[5]||(e[5]=[t("figure",null,[t("img",{src:"https://upload.r2.lb.chasm.cloud/2025/10/ApplicationFrameHost_tEukp4Wsec.png",alt:"",width:"500",tabindex:"0"}),t("figcaption")],-1)])]),_:1})]),_:1}),e[19]||(e[19]=l('<ul><li><strong>Go Back</strong>: Return to the application <a href="#home">home screen</a></li><li><strong>Clear Points</strong>: Clear any collected survey points from the device memory.</li><li><strong>Send to cloud</strong>: Send any collected survey points to the cloud, where they can be <a href="/docs/pr/24/apps/admin/devices/forwarding">forwarded to other services</a>, or viewed using <a href="/docs/pr/24/apps/chasm/share/">share.chasm.cloud</a>.</li><li><strong>RTK</strong>: Can be used to toggle the <a href="/docs/pr/24/devices/api/messages/39-gps-control">RTK corrections data</a> on or off.</li><li><strong>Mode</strong>: Can be used to toggle between various survey modes.</li><li><strong>Auto</strong>: Can be used to toggle automatic point collection on or off, based on a calculated distance from last point for the auto mode.</li><li><strong>Stop</strong>: Stop any ongoing survey.</li><li><strong>Exit</strong>: Exit the survey application, returning to the main device application, or previous application selection screen.</li></ul><h2 id="surveying" tabindex="-1">Surveying <a class="header-anchor" href="#surveying" aria-label="Permalink to &quot;Surveying&quot;">​</a></h2><p>To start a survey, press the <code>Start</code> button on the home screen or web app.</p><p>You&#39;ll see the page update to show the current survey status, as it attempts to get a GNSS and RTK fix.</p>',4)),o(s,null,{default:i(()=>[o(a,{label:"E-Ink"},{default:i(()=>[...e[6]||(e[6]=[t("figure",null,[t("img",{src:"https://upload.r2.lb.chasm.cloud/2025/10/ApplicationFrameHost_TkfFFtmRdE.png",alt:"",width:"500",tabindex:"0"}),t("figcaption")],-1)])]),_:1}),o(a,{label:"Web App"},{default:i(()=>[...e[7]||(e[7]=[t("figure",null,[t("img",{src:"https://upload.r2.lb.chasm.cloud/2025/10/chrome_p2KHTFZb3v.png",alt:"",width:"500",tabindex:"0"}),t("figcaption")],-1)])]),_:1})]),_:1}),e[20]||(e[20]=t("p",null,"As the GNSS fix is acquired, the status will update to show the current number of satellites, and the current accuracy, fix type, and coordinate location.",-1)),o(s,null,{default:i(()=>[o(a,{label:"E-Ink"},{default:i(()=>[...e[8]||(e[8]=[t("figure",null,[t("img",{src:"https://upload.r2.lb.chasm.cloud/2025/10/chrome_8KDy4Fm9K7.png",alt:"",width:"500",tabindex:"0"}),t("figcaption")],-1)])]),_:1}),o(a,{label:"Web App"},{default:i(()=>[...e[9]||(e[9]=[t("figure",null,[t("img",{src:"https://upload.r2.lb.chasm.cloud/2025/10/chrome_JbsaLxjqMa.png",alt:"",width:"500",tabindex:"0"}),t("figcaption")],-1)])]),_:1})]),_:1}),e[21]||(e[21]=t("h3",{id:"button-mode",tabindex:"-1"},[n("Button mode "),t("a",{class:"header-anchor",href:"#button-mode","aria-label":'Permalink to "Button mode"'},"​")],-1)),e[22]||(e[22]=t("p",null,[n("When in button mode (the default), you can manually collect points by pressing the center "),t("code",null,"Store"),n(" button, or the "),t("code",null,"Store"),n(" button on the web app.")],-1)),e[23]||(e[23]=t("p",null,"Doing so will collect the more recently receive GNSS point, and add it to the list of collected points.",-1)),e[24]||(e[24]=t("p",null,"The last 2 points collected will be shown on the screen E-Ink screen, along with the total number of points collected.",-1)),e[25]||(e[25]=t("p",null,"The web app will show a larger list of the most recently collected points.",-1)),o(s,null,{default:i(()=>[o(a,{label:"E-Ink"},{default:i(()=>[...e[10]||(e[10]=[t("figure",null,[t("img",{src:"https://upload.r2.lb.chasm.cloud/2025/10/chrome_TI8Nrk7D1a.png",alt:"",width:"500",tabindex:"0"}),t("figcaption")],-1)])]),_:1}),o(a,{label:"Web App"},{default:i(()=>[...e[11]||(e[11]=[t("figure",null,[t("img",{src:"https://upload.r2.lb.chasm.cloud/2025/10/chrome_f7N2pImSqj.png",alt:"",width:"500",tabindex:"0"}),t("figcaption")],-1)])]),_:1})]),_:1}),e[26]||(e[26]=l('<h3 id="continuous-mode" tabindex="-1">Continuous mode <a class="header-anchor" href="#continuous-mode" aria-label="Permalink to &quot;Continuous mode&quot;">​</a></h3><p>When in continuous mode, points will be automatically collected based on the distance moved from the last collected point.</p><p>To activate continuous mode, navigate to the <a href="#actions">Actions</a> menu, and select the <code>Mode</code> option until <code>Continuous</code> is shown. You can then select the continuous distance using the <code>Distance</code> option.</p><div class="tip custom-block"><p class="custom-block-title">⚡ Tip</p><p>You may want to acquire a good GNSS fix before starting continuous mode, to avoid collecting points with poor accuracy, as the application will still calculate distance based on these GNSS points.</p></div><p>When in continuous mode, and a survey is in progress, the middle button will no longer collect points.</p>',5)),o(s,null,{default:i(()=>[o(a,{label:"E-Ink"},{default:i(()=>[...e[12]||(e[12]=[t("figure",null,[t("img",{src:"https://upload.r2.lb.chasm.cloud/2025/10/chrome_tI7unbjce6.jpg",alt:"",width:"500",tabindex:"0"}),t("figcaption")],-1)])]),_:1})]),_:1}),e[27]||(e[27]=l('<h2 id="cloud-submission" tabindex="-1">Cloud submission <a class="header-anchor" href="#cloud-submission" aria-label="Permalink to &quot;Cloud submission&quot;">​</a></h2><p>The RH2 device will be sending periodic location updates to the cloud while a survey is in progress if you have RTK corrections enabled, or have a cloud position subscription activated (the default for new devices).</p><p>However, the collected survey points can be sent in addition to this, with extra headers, that publish them directly to <a href="/docs/pr/24/apps/chasm/share/">share.chasm.cloud</a>.</p><p>To send the collected points to the cloud, navigate to the <a href="#actions">Actions</a> menu, and select the <code>Send to cloud</code> option.</p><p>You should see a green LED flash per successfully sent point, or a red LED flash if there was an error sending a point.</p><p>From the <a href="#info">Info</a> screen, you can note the <code>Share</code> code, which can be used to view the submitted points using <a href="/docs/pr/24/apps/chasm/share/">share.chasm.cloud</a>, using the format <code>YYYYMMDD-&lt;share code&gt;</code>, e.g. <code>20250930-af3ge911e5</code>.</p><h3 id="our-carpark" tabindex="-1">Our Carpark <a class="header-anchor" href="#our-carpark" aria-label="Permalink to &quot;Our Carpark&quot;">​</a></h3><p>An example of using the button mode to collect points around our carpark, and sending the points to the cloud is accessible using <a href="https://share.chasm.cloud/#10579203/20250930-1f3ce921e8" target="_blank" rel="noreferrer">https://share.chasm.cloud/#10579203/20250930-1f3ce921e8</a></p><figure><img src="https://upload.r2.lb.chasm.cloud/2025/10/chrome_fNPGAz03uf.png" alt="" tabindex="0"><figcaption></figcaption></figure><p>You can see further documentation on using <a href="/docs/pr/24/apps/chasm/share/">share.chasm.cloud</a> to view and export the data in various formats.</p><h2 id="code" tabindex="-1">Code <a class="header-anchor" href="#code" aria-label="Permalink to &quot;Code&quot;">​</a></h2><p>The Toit application code is open source, and available on <a href="https://github.com/lightbug-io/toit-lightbug/blob/main/src/apps/survey/survey.toit" target="_blank" rel="noreferrer">GitHub</a>, currently comprising of just under 1000 lines of custom code.</p><p>As some of the patterns used in the application are factored out into the core Lightbug SDK, we expect the number of lines of code required for similar applications to reduce over time.</p><h2 id="known-limitations" tabindex="-1">Known Limitations <a class="header-anchor" href="#known-limitations" aria-label="Permalink to &quot;Known Limitations&quot;">​</a></h2><ul><li>The application is designed for demo purposes, initially to showcase the Toit capabilities of the RH2 device, and is not intended for use on other devices, or for production use.</li><li>Entering any WiFi details by hand will in future be improved with QR codes, as will linking to <a href="/docs/pr/24/apps/chasm/share/">share.chasm.cloud</a> shared sets of data.</li><li>A hybrid mode for point collection (manual button pressed and automatic distance) is not currently supported, but has been requested, and may be added in the future.</li><li>Button presses are currently only sent between processors on releasing the button, which leads to some unnecessary delays in the UI updates, due to the way that the <a href="/docs/pr/24/devices/api/messages/38-button-press">button press message and subscriptions work</a>. We will be introducing an additional message type to allow for immediate button press notifications in the future (on press, not after press).</li><li>Button presses and menu synchronization : Currently the application doesn&#39;t know which menu items are selected, only which buttons are pressed through time. As a result the application can decide differing options are being selected. This will be fixed with &quot;menu selection information&quot; being sent alongside button presses in the future.</li><li>100 point limit for surveys, which should be sufficient for demo purposes, but may be too low for some use cases. The application currently only stores points in memory, and does not persist them to flash. The final release of the RH2 will come with additional memory, and Toit applications can also use of <a href="https://libs.toit.io/system/storage/class-Bucket" target="_blank" rel="noreferrer">buckets</a> to store data persistently and allow for more point storage.</li></ul>',15))])}const T=d(p,[["render",h]]);export{y as __pageData,T as default};
